  "wealthDetail.property.holdNeutral": "شامل ڪريو خريداري جو سال ۽ قيمت رکيل مشوري لاءِ",
  "wealthDetail.property.holdNeutralDetail": "داخل ڪريو جڏھن توھان خريد ڪيو ۽ ڪھڙي قيمت تي ان لاڪ ڪرڻ لاءِ CAGR، انفرافيشن سان ترتيب ڏنل واپسي، ۽ ھدايت رکو.",
  "wealthDetail.property.holdModerate": "رکڻ جي لائق - معمولي حقيقي حاصلات",
  "wealthDetail.property.holdModerateDetail": "نامناسب واڌارو انفرافيشن کي گڏيل بنيادن تي مات ڏئي ٿو، پر حقيقي واپسي اعتدال پسند آهي. رکو جيڪڏهن توهان کي لياقت جي ضرورت ناهي؛ وڪڻڻ صرف هڪ مضبوط ٻيهر سيڙپڪاري جي منصوبي يا زندگي جي واقعي جي نقد جي ضرورت لاءِ احساس رکي ٿو.",
  "wealthDetail.property.holdMature": "بالغ هولڊ - دولت جو دڪان، تڪڙو نقد نه",
  "wealthDetail.property.holdMatureDetail": "You have held long enough to ride multiple cycles. Real returns are positive but modest — this asset works as generational wealth and inflation hedge. Avoid selling unless relocation, debt payoff, or diversification clearly wins after tax and brokerage.",
  "wealthDetail.property.realReturnNote": "Assumes ~{inflation}% annual inflation (India long-run average).",
  "wealthDetail.property.deepAnalysis": "رکو ۽ مارڪيٽ تجزيو",
  "wealthDetail.property.yearsToTarget": "موجوده رفتار تي، ~{years} وڌيڪ سال 12٪ CAGR ٽارگيٽ تائين پهچڻ لاءِ.",
  "wealthDetail.property.outlookMetro": "Metro corridors: infra (metro lines, IT parks) often lifts land values — watch local RERA/project news.",
  "wealthDetail.property.outlookTier2": "Tier-2 cities: industrial corridors and highway links can accelerate appreciation in 5–8 year cycles.",
  "wealthDetail.property.outlookTier3": "Smaller towns: liquidity is lower — favour long holds and verify title before major price revisions.",
  "wealthDetail.property.outlookAreaFallback": "توهان جو علائقو",
  "wealthDetail.property.purchaseThen": "Purchase price (then)",
  "wealthDetail.property.inflationCostToday": "انفرافيشن سان ترتيب ڏنل قيمت (اڄ)",
  "wealthDetail.property.inflationCostHint": "توهان جي موجوده قيمت نه آهي - اڄ جي روپين ۾ اصل خريداري جي قيمت ڇا آهي.",
  "wealthDetail.property.narrative.inflationAdjustedCost": "Your ₹{purchase} purchase equals roughly ₹{todayEquivalent} in today's money after {years} years at ~{inflation}% compounded inflation — real growth is measured against that, not the original price alone.",
  "wealthDetail.property.narrative.purchaseDerived": "خريداري جي قيمت اچي ٿي شرح کان × ايريا جيڪا توهان داخل ڪئي آهي - ٽيپ ڪريو ايڊٽ ڪريو جيڪڏهن ڪل غلط لڳي ٿي.",
  "wealthDetail.property.narrative.realReturnExplain": "Nominal CAGR {cagr}% minus ~{inflation}% inflation ≈ {real}% real return per year — property often looks strong in rupee terms while barely beating inflation after costs.",
  "wealthDetail.property.narrative.vsBenchmarkExplain": "Your {cagr}% CAGR vs ~{benchmark}% typical for this city tier ({delta}% difference) — use as a rough peer check, not a buy/sell signal.",
  "wealthDetail.property.narrative.longHoldLiquidity": "لانگ هولڊز وقت جي خطري کي گھٽائي ٿو پر سرمائي کي بند ڪري ٿو - 6-12 مھينن جي خرچن کي ٻي جاءِ تي رکڻ کان اڳ ھن کي وڪرو لائق دولت سمجھڻ کان اڳ.",
  "wealthDetail.property.narrative.rentYieldExplain": "Estimated gross rent yield ~{yield}% — compare with FD/PPF after tax; if you live in the property, treat rent savings as implicit yield.",
  "wealthDetail.property.narrative.rentVsIncome": "جيڪڏهن مڪمل طور تي ڪرائي تي ڏنو ويو آهي، مجموعي کرايه هوندو ~{pct}% توهان جي اعلان ڪيل مهيني آمدني جو - چيڪ ڪريو ته ڇا اهو توهان جي حقيقي يا حاصل ڪرڻ واري ڪرائي سان ملندو آهي.",
  "wealthDetail.property.narrative.valueVsIncome": "هي اثاثو آهي ~{multiple}× توهان جي سالياني آمدني ڪاغذن تي - هڪ وڏو ڪنسنٽريشن؛ عنصر جيڪو هنگامي ۽ تنوع جي منصوبابندي ۾.",
  "wealthDetail.property.narrative.highValueTier3Liquidity": "هن قيمت تي هڪ ننڍڙي شهر ۾، خريد ڪندڙ ڳولڻ مهينو وٺي سگھي ٿو - قيمت حقيقي طور تي ۽ فوري طور تي دستياب نقد جي طور تي مڪمل قيمت ڳڻڻ کان بچڻ.",
  "wealthDetail.property.narrative.highValueTier2Liquidity": "هڪ ٽائر-2 مارڪيٽ لاءِ اعليٰ ٽڪيٽ - توهان جي بيان ڪيل قيمت تي جلدي مائعيت کي فرض ڪرڻ کان پهريان ويجهي رجسٽرڊ سيلز جي تصديق ڪريو.",
  "wealthDetail.property.narrative.targetCagrReality": "ھتان کان 12٪ CAGR جو تعاقب ڪندي اڄ جي رفتار تي ~{years} وڌيڪ سال لڳندا - توھان جو ھولڊنگ اڳ ۾ ئي مضبوط نامزدگي حاصل ڪري چڪو آھي. مستقبل جي واپسي عام ٿي سگھي ٿي.",
  "wealthDetail.property.narrative.landHold": "زمين: گھٽ ۾ گھٽ سار سنڀال پر سستي لياقت - 10+ سال افق لاءِ بھترين؛ لسٽنگ کان پهريان تڪليف، زوننگ، ۽ روڊ جي ويڪرائي نوٽيفڪيشن چيڪ ڪريو.",
  "wealthDetail.property.narrative.commercialHold": "تجارتي: خالي جاءِ ۽ نوڪردار جي معيار جيتري اهميت رکي ٿي جڳهه جيتري قدر - ٻيهر اندازو لڳايو ته فوٽفال يا ليز جون شرطون ڪمزور ٿيون.",
  "wealthDetail.property.narrative.residentialHold": "رهائشي: خود استعمال وڪرو ڪرڻ لاء دٻاء گھٽائي ٿو. جيڪڏهن ڪرائي تي ڏنو وڃي، ٽريڪٽر ٽرين اوور ۽ سوسائٽي جي سار سنڀال جي واڌاري.",
  "wealthDetail.property.narrative.verifyTitle": "ڪنهن به وڪري کان اڳ: انڪمبرنس سرٽيفڪيٽ، پراپرٽي ٽيڪس جون رسيدون، ۽ ميوٽيشن اسٽيٽس - دير هتي ڪاغذ جي حاصلات کي ختم ڪري ٿي.",
